function dropDigits(num: string, k: number): string {
  let s = num;
  for (let t = 0; t < k; t++) {
    let i = 0;
    while (i + 1 < s.length && s[i] <= s[i + 1]) i++;
    s = s.slice(0, i) + s.slice(i + 1);
  }
  s = s.replace(/^0+/, "");
  return s === "" ? "0" : s;
}

