function dropDigits(num: string, k: number): string {
  const stack: string[] = [];
  for (const d of num) {
    while (k > 0 && stack.length && stack[stack.length - 1] > d) {
      stack.pop();
      k--;
    }
    stack.push(d);
  }
  stack.length -= Math.min(k, stack.length); // leftover deletions come off the end
  let i = 0;
  while (i < stack.length && stack[i] === "0") i++;
  return i === stack.length ? "0" : stack.slice(i).join("");
}

