        stack = []
        for d in num:
            while k and stack and stack[-1] > d:
                stack.pop()
                k -= 1
            stack.append(d)
        if k:
            stack = stack[:-k]  # leftover deletions come off the end
        return "".join(stack).lstrip("0") or "0"

